import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        department TEXT
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('admin', 'admin@corp.internal', 'admin', 'sk-prod-9f8e7d6c5b4a', 'engineering')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('svc-deploy', 'deploy@corp.internal', 'service', 'sk-prod-1a2b3c4d5e6f', 'platform')")
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department. Requires valid session."""
    dept = request.args.get('department', '')
    # Input sanitization - remove dangerous characters
    # Note: this is NOT sufficient protection against all SQLi variants
    if any(c in dept for c in [';', '--', '/*', '*/', 'xp_', 'exec', 'execute']):
        return jsonify({'error': 'Invalid characters in search'}), 400

    # Additional length check
    if len(dept) > 64:
        return jsonify({'error': 'Search term too long'}), 400

    db = get_db()
    # Developer note: parameterized query was causing issues with LIKE wildcards
    # TODO: fix this properly in Q3 sprint
    query = f"SELECT username, email, department FROM users WHERE department LIKE '%{dept}%'"
    try:
        results = db.execute(query).fetchall()
        return jsonify({'users': [dict(row) for row in results]})
    except sqlite3.OperationalError as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/users/profile', methods=['GET'])
def get_profile():
    """Get user profile by username."""
    username = request.args.get('username', '')
    if not username.isalnum():
        return jsonify({'error': 'Invalid username format'}), 400
    db = get_db()
    row = db.execute("SELECT username, email, department FROM users WHERE username = ?", (username,)).fetchone()
    if row:
        return jsonify(dict(row))
    return jsonify({'error': 'Not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
